#!/usr/bin/env python3
"""spec-rsi-root.py — N0a (retrieval scope + seed records) verifier.

MetaTask v1.3 competitive-mode verifier (protocol draft §4.3 CI-style contract).

Artifact contract: metafile bundle: scope.md + records-seed.json (>=20 records).

Environment (§4.3): METATASK_ARTIFACT_URI / METATASK_NODE / METATASK_TASKID /
  METATASK_DOWNLOAD_BASE (metafile resolution: <base>/file/<urlencoded URI>) /
  METATASK_RESOLVE=0 disables live link resolution (offline dry runs);
  METATASK_INSECURE=1 allows an unverified TLS context when no CA store exists.

Exit codes: 0 pass (evidence on stdout) · 1 fail (reason on stderr) ·
2 invalid (null / empty / unresolvable input). The pass path asserts the
enumeration closure: the check counter must equal EXPECTED_CHECKS.
"""
import io
import json
import os
import re
import sys
import tarfile
import urllib.error
import urllib.parse
import urllib.request
import zipfile

EXPECTED_CHECKS = 8

checks_done = 0


def ok(msg):
    global checks_done
    checks_done += 1
    print("OK   " + msg)


def emit(verdict, detail):
    print(json.dumps({"verdict": verdict, "detail": detail, "checks": checks_done}, ensure_ascii=False))


def closure():
    """Assert the enumeration closure without consuming a check slot."""
    if checks_done != EXPECTED_CHECKS:
        die_fail("enumeration closure: %d/%d checks" % (checks_done, EXPECTED_CHECKS))
    print("OK   enumeration closure: %d/%d checks" % (checks_done, EXPECTED_CHECKS))


def die_fail(msg):
    emit("fail", msg)
    print("FAIL: " + msg, file=sys.stderr)
    sys.exit(1)


def die_invalid(msg):
    emit("invalid", msg)
    sys.exit(2)


def check(cond, msg):
    if not cond:
        die_fail(msg)
    ok(msg)


def _guard(exc_type, exc, tb):
    """Any unhandled error is INVALID input, never a fail verdict."""
    if issubclass(exc_type, SystemExit):
        return
    emit("invalid", "unhandled %s: %s" % (exc_type.__name__, exc))
    sys.exit(2)


sys.excepthook = _guard


def ssl_context():
    """CA bundle for HTTPS: certifi when available; METATASK_INSECURE=1 opts out.

    The host Python on some macOS installs ships without the system CA store, so
    a bare urlopen fails SSL verification while curl succeeds. Reviewers get a
    documented opt-out, and every use is logged as reduced evidence.
    """
    import ssl
    try:
        import certifi
        ctx = ssl.create_default_context(cafile=certifi.where())
    except Exception:  # noqa: BLE001
        ctx = ssl.create_default_context()
    if os.environ.get("METATASK_INSECURE") == "1":
        print("NOTE ssl verification disabled (METATASK_INSECURE=1) — resolution evidence is weaker")
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
    return ctx


def artifact_uri():
    uri = os.environ.get("METATASK_ARTIFACT_URI", "").strip()
    if not uri:
        die_invalid("METATASK_ARTIFACT_URI is empty")
    return uri


def fetch_bytes(uri):
    if uri.startswith(("metafile://", "pin://")):
        base = os.environ.get("METATASK_DOWNLOAD_BASE", "").strip()
        if not base:
            die_invalid("METATASK_DOWNLOAD_BASE unset — cannot resolve " + uri)
        url = base.rstrip("/") + "/file/" + urllib.parse.quote(uri, safe="")
        path = None
    elif uri.startswith("file://"):
        url, path = None, uri[7:]
    else:
        url, path = None, uri
    try:
        if url:
            req = urllib.request.Request(url, headers={"User-Agent": "metatask-spec/1.0"})
            with urllib.request.urlopen(req, timeout=60, context=ssl_context()) as resp:
                return resp.read()
        with open(path, "rb") as fh:
            return fh.read()
    except Exception as exc:  # noqa: BLE001 - any fetch failure is an invalid run
        die_invalid("artifact fetch failed for %s: %r" % (uri, exc))


def load_members(data):
    """Return {name: bytes} for an archive, or {"__raw__": decoded text}."""
    if data[:2] != b"\x1f\x8b" and data[:2] != b"PK":
        return {"__raw__": data.decode("utf-8", "replace")}

    members = {}
    if data[:2] == b"PK":
        with zipfile.ZipFile(io.BytesIO(data)) as arc:
            names = [n for n in arc.namelist() if not n.endswith("/")]
            for name in names:
                members[name] = arc.read(name)
    else:
        with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as arc:
            names = [n for n in arc.getnames() if not n.endswith("/")]
            for name in names:
                handle = arc.extractfile(name)
                if handle is not None:
                    members[name] = handle.read()

    if not members:
        die_invalid("artifact archive is empty — nothing to verify")

    tops = {n.split("/")[0] for n in members if "/" in n}
    if len(tops) == 1:
        top = sorted(tops)[0]
        if all(n.startswith(top + "/") for n in members):
            members = {n[len(top) + 1:]: v for n, v in members.items()}
    return members


def text_of(members, name):
    if name in members:
        return members[name].decode("utf-8", "replace")
    raw = members.get("__raw__")
    if raw is not None and name.endswith(".md"):
        return raw
    return None


def as_text(value):
    if isinstance(value, (bytes, bytearray)):
        return value.decode("utf-8", "replace")
    return value


def json_of(members, name):
    for key in (name, "__raw__"):
        if key not in members:
            continue
        text = as_text(members[key])
        if not isinstance(text, str):
            return None
        try:
            return json.loads(text)
        except Exception:  # noqa: BLE001
            if key == name:
                die_fail("%s is present but is not valid JSON" % name)
            return None
    return None


META_BLOCK_RE = re.compile(r"<!--\s*meta:.*?-->", re.S)


def body_only(doc):
    """The document without its machine-readable meta declarations.

    Declarations must never satisfy a check about the document body: strip them
    first, or a document that declares 50 citations and writes nothing passes.
    """
    return META_BLOCK_RE.sub("", doc)


def raw_list(value):
    if value is None:
        return []
    return [x.strip() for x in value.split(",") if x.strip()]


def resolve_ratio(urls):
    """Live-resolve links. Returns (good, total) or None when disabled."""
    if os.environ.get("METATASK_RESOLVE", "1") == "0":
        return None
    good = 0
    for url in urls:
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (metatask-spec)"})
            with urllib.request.urlopen(req, timeout=20, context=ssl_context()) as resp:
                if resp.status == 200:
                    good += 1
        except urllib.error.HTTPError as exc:
            if exc.code >= 500:
                die_invalid("server error %s while resolving %s" % (exc.code, url))
        except Exception as exc:  # noqa: BLE001
            die_invalid("network unavailable while resolving links: %r" % exc)
    return good, len(urls)


def meta_block(doc, key):
    """Read <!-- meta: key=value --> from a document."""
    hit = re.search(r"<!--\s*meta:\s*" + key + r"=([^>]*?)-->", doc)
    return hit.group(1).strip() if hit else None


def id_list(value):
    if value is None:
        return None
    return sorted(x.strip() for x in value.split(",") if x.strip())

# --- N0a: retrieval-scope bundle (scope.md + records-seed.json) -----------------

ARTIFACT = artifact_uri()
members = load_members(fetch_bytes(ARTIFACT))
scope = text_of(members, "scope.md")
seed = json_of(members, "records-seed.json")
check(scope is not None and seed is not None, "bundle carries scope.md and records-seed.json")

SCHEMA_FIELDS = ("arxiv_id", "title", "year", "venue", "mechanism_tag", "evidence_type", "contribution", "link")
absent = [f for f in SCHEMA_FIELDS if f not in (scope or "")]
check(not absent, "scope.md names all 8 record schema fields (absent: %s)" % (absent or "none"))

queries = re.findall(r"^\s*[-*]\s+\S.*$", scope or "", re.MULTILINE)
check("检索式" in (scope or "") and len(queries) >= 8,
      "scope.md declares a 检索式 section with >= 8 query lines (got %d list lines)" % len(queries))
check("排除" in (scope or ""),
      "scope.md declares an explicit exclusion rule section")

check(isinstance(seed, list) and len(seed) >= 20,
      "records-seed.json is an array with >= 20 records (got %s)" % (len(seed) if isinstance(seed, list) else "n/a"))

FIELDS = ("arxiv_id", "title", "year", "venue", "mechanism_tag", "evidence_type", "contribution", "link")
missing = [r.get("arxiv_id", "?") for r in seed if not all(str(r.get(f, "")).strip() for f in FIELDS)]
check(not missing, "every seed record carries all 8 schema fields (missing on: %s)" % (missing or "none"))

bad_link = [r.get("arxiv_id") for r in seed
            if not re.match(r"^\d{4}\.\d{4,5}$", str(r.get("arxiv_id", "")))
            or r.get("link") != "https://arxiv.org/abs/" + str(r.get("arxiv_id"))]
check(not bad_link, "every record link is the arXiv abs URL of its own arxiv_id (bad: %s)" % (bad_link or "none"))

ids = [r.get("arxiv_id") for r in seed]
check(len(ids) == len(set(ids)), "seed arxiv_ids are unique")

closure()
emit("pass", "scope + %d seed records verified" % len(seed))
